1	// === Types ===
2	type Customer = { yearsWithMHPCO: number };
3	type Item = { type: string; cursed?: boolean; enchantment?: number };
4	type Damage = { itemType: string; amount: number };
5	type Incident = { cause: string; damages: Damage[] };
6	type QuoteStep = { op: "quote"; items: Item[] };
7	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
8	type Step = QuoteStep | ClaimStep;
9	type Scenario = { customer: Customer; steps: Step[] };
10	type Policy = { items: Item[]; remainingCap: number };
11	
12	// === Premium constants ===
13	const PROCESSING_FEE = 5;
14	const FIRST_INSURANCE_RATE = 0.1;
15	const LOYALTY_DISCOUNT_RATE = 0.2;
16	const LOYALTY_YEARS_THRESHOLD = 2;
17	const FOLLOWUP_DISCOUNT_RATE = 0.15;
18	const CURSE_RATE = 0.5;
19	const HIGH_ENCHANTMENT_RATE = 0.3;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	// === Component-block constants ===
32	const BLOCK_SIZE = 3;
33	const COMPONENT_BLOCK_PRICE = 60;
34	const COMPONENT_TYPES = ["rune", "moonstone"];
35	
36	// === Policy / claim constants ===
37	const DEDUCTIBLE = 100;
38	const CAP_MULTIPLIER = 2;
39	const INSURANCE_VALUE_MULTIPLIER = 10;
40	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
41	const HALF_REIMBURSEMENT_RATE = 0.5;
42	
43	// === Generic helpers ===
44	const sumBy = <T>(items: T[], selector: (item: T) => number): number =>
45	  items.reduce((sum, item) => sum + selector(item), 0);
46	
47	const rateIfApplies = (applies: boolean, base: number, rate: number): number =>
48	  applies ? base * rate : 0;
49	
50	// === Base premium ===
51	const basePremium = (item: Item): number => {
52	  const price = BASE_PREMIUMS[item.type];
53	  if (price === undefined) throw new Error(`unknown item type: ${item.type}`);
54	  return price;
55	};
56	
57	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
58	
59	const isHighlyEnchanted = (item: Item): boolean =>
60	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD;
61	
62	const itemSurcharge = (item: Item): number => {
63	  const base = basePremium(item);
64	  return rateIfApplies(item.cursed ?? false, base, CURSE_RATE)
65	       + rateIfApplies(isHighlyEnchanted(item), base, HIGH_ENCHANTMENT_RATE);
66	};
67	
68	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE && COMPONENT_TYPES.includes(sameTypeItems[0].type);
70	
71	const groupBasePremium = (sameTypeItems: Item[]): number =>
72	  isComponentBlock(sameTypeItems) ? COMPONENT_BLOCK_PRICE : sumBy(sameTypeItems, basePremium);
73	
74	const groupByType = (items: Item[]): Item[][] => {
75	  const byType = new Map<string, Item[]>();
76	  for (const item of items) {
77	    const bucket = byType.get(item.type) ?? [];
78	    bucket.push(item);
79	    byType.set(item.type, bucket);
80	  }
81	  return [...byType.values()];
82	};
83	
84	const totalBasePremium = (items: Item[]): number =>
85	  sumBy(groupByType(items), groupBasePremium);
86	
87	// === Policy-wide premium modifiers ===
88	const isLoyal = (customer: Customer): boolean =>
89	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
90	
91	const loyaltyDiscount = (base: number, customer: Customer): number =>
92	  rateIfApplies(isLoyal(customer), base, LOYALTY_DISCOUNT_RATE);
93	
94	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
95	
96	const followupDiscount = (base: number, isFollowup: boolean): number =>
97	  rateIfApplies(isFollowup, base, FOLLOWUP_DISCOUNT_RATE);
98	
99	const perItemSurcharges = (items: Item[]): number => sumBy(items, itemSurcharge);
100	
101	const premiumForItems = (items: Item[], customer: Customer, isFollowup: boolean): number => {
102	  const base = totalBasePremium(items);
103	  const surcharges = perItemSurcharges(items) + firstInsuranceSurcharge(base);
104	  const discounts = loyaltyDiscount(base, customer) + followupDiscount(base, isFollowup);
105	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
106	};
107	
108	// === Insurance / cap ===
109	const insuranceValue = (item: Item): number => basePremium(item) * INSURANCE_VALUE_MULTIPLIER;
110	
111	const insuranceSum = (items: Item[]): number => sumBy(items, insuranceValue);
112	
113	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
114	
115	// === Claim payout ===
116	const qualifiesForHalfReimbursement = (item: Item): boolean =>
117	  enchantmentLevel(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
118	
119	const reimbursementRate = (item: Item): number =>
120	  qualifiesForHalfReimbursement(item) ? HALF_REIMBURSEMENT_RATE : 1;
121	
122	const applyDeductible = (amount: number): number => Math.max(0, amount - DEDUCTIBLE);
123	
124	const findInsuredItem = (items: Item[], itemType: string): Item => {
125	  const item = items.find((i) => i.type === itemType);
126	  if (item === undefined) throw new Error(`uninsured item type: ${itemType}`);
127	  return item;
128	};
129	
130	const damagePayout = (damage: Damage, items: Item[]): number => {
131	  if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
132	  const item = findInsuredItem(items, damage.itemType);
133	  return applyDeductible(damage.amount * reimbursementRate(item));
134	};
135	
136	// === Step handlers ===
137	const handleQuote = ({ items }: QuoteStep, customer: Customer, policies: Policy[]) => {
138	  const isFollowup = policies.length > 0;
139	  const premium = premiumForItems(items, customer, isFollowup);
140	  policies.push({ items, remainingCap: policyCap(items) });
141	  return { premium };
142	};
143	
144	const countBy = <T>(items: T[], key: (item: T) => string): Map<string, number> => {
145	  const counts = new Map<string, number>();
146	  for (const item of items) counts.set(key(item), (counts.get(key(item)) ?? 0) + 1);
147	  return counts;
148	};
149	
150	const assertDamageCounts = (damages: Damage[], items: Item[]): void => {
151	  const itemCounts = countBy(items, (i) => i.type);
152	  const damageCounts = countBy(damages, (d) => d.itemType);
153	  for (const [type, count] of damageCounts) {
154	    if (count > (itemCounts.get(type) ?? 0)) {
155	      throw new Error(`more damages of type ${type} than insured`);
156	    }
157	  }
158	};
159	
160	const claimPayout = (damages: Damage[], policy: Policy): number => {
161	  assertDamageCounts(damages, policy.items);
162	  const rawPayout = sumBy(damages, (d) => damagePayout(d, policy.items));
163	  return Math.min(Math.floor(rawPayout), policy.remainingCap);
164	};
165	
166	const handleClaim = ({ policy: policyIndex, incident }: ClaimStep, policies: Policy[]) => {
167	  const policy = policies[policyIndex];
168	  const payout = claimPayout(incident.damages, policy);
169	  policy.remainingCap -= payout;
170	  return { payout, remainingCap: policy.remainingCap };
171	};
172	
173	export const runScenario = ({ customer, steps }: Scenario): unknown => {
174	  const policies: Policy[] = [];
175	  const results = steps.map((step) =>
176	    step.op === "quote" ? handleQuote(step, customer, policies) : handleClaim(step, policies),
177	  );
178	  return { results };
179	};
